FUNCTION "FC_ArrayTotal" : DInt
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
VAR_INPUT
    Values : Array[0..3] of Int;
    Mode : Int;
END_VAR
VAR_TEMP
    Index : Int;
