// ============================================================================
//  FB_BasicLatch —— 启动/停止/故障/复位 保持（自锁）功能块
//  ---------------------------------------------------------------------------
//  功能：实现带故障闭锁的标准启停自锁逻辑。故障优先停机并闭锁，复位清除故障，
//        停止与故障均使输出失活；仅在使能且无故障时输出激活。
//  适用：S7-1200 / S7-1500（优化访问）。典型电机/泵启停控制骨架。
//  作者：TIA MCP 示例库     版本：0.2
// ============================================================================
FUNCTION_BLOCK "FB_BasicLatch"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.2
   VAR_INPUT
      Enable     : Bool;   // 启动请求：为 TRUE 且无故障时使输出激活
      Disable    : Bool;   // 停止请求：高电平使输出失活
      FaultInput : Bool;   // 故障输入：为 TRUE 时闭锁故障并立即停机
      Reset      : Bool;   // 复位：清除已闭锁的故障（高电平有效）
   END_VAR

   VAR_OUTPUT
      Active  : Bool;   // 输出激活（运行中）
      Fault   : Bool;   // 故障闭锁中
      Healthy : Bool;   // 健康：无故障，可运行
   END_VAR

   VAR
      ActiveLatch : Bool;   // 内部运行自锁位
      FaultLatch  : Bool;   // 内部故障闭锁位
   END_VAR

BEGIN
   // --- 故障闭锁与复位（故障优先） ----------------------------------------
   IF FaultInput THEN
      FaultLatch  := TRUE;     // 出现故障：闭锁故障
      ActiveLatch := FALSE;    // 并立即停机
   ELSIF Reset THEN
      FaultLatch := FALSE;     // 复位：清除故障闭锁
   END_IF;

   // --- 启停自锁（停止/故障优先于启动） -----------------------------------
   IF Disable OR FaultLatch THEN
      ActiveLatch := FALSE;                    // 停止或故障：失活
   ELSIF Enable AND NOT FaultLatch THEN
      ActiveLatch := TRUE;                     // 启动且无故障：激活
   END_IF;

   // --- 输出映射 ----------------------------------------------------------
   Active  := ActiveLatch;
   Fault   := FaultLatch;
   Healthy := NOT FaultLatch;                  // 无故障即为健康
END_FUNCTION_BLOCK

// ============================================================================
//  FB_SelfTest_Template —— DB 驱动的最小 SCL 自测骨架
//  ---------------------------------------------------------------------------
//  功能：把「被测逻辑」放进 RunCase，用一张用例表（预期值/实际值）逐条跑，
//        统计通过/失败计数，给出 Done/AllPassed。用例表和控制位放在实例 DB
//        或全局 DB 里，HMI/监控表置 Start 即可触发，不需要在线改程序。
//  用法：1) 把被测 FC/FB 调用写进 RunCase 区（示例为线性缩放）；
//        2) 在 Cases[] 里填 Input / Expected；
//        3) 监控表置 Start := TRUE，读 PassCount / FailCount / FirstFailIndex。
//  适用：S7-1200 / S7-1500（优化访问）。模式借鉴社区 SCL 单元测试思路，代码全新编写。
//  注意：这是工程内自检，不是 Siemens 质量判定；上线前仍需 TIA 编译与规范审查。
//  作者：TIA MCP 示例库     版本：0.1
// ============================================================================
FUNCTION_BLOCK "FB_SelfTest_Template"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT
      Start   : Bool;   // 上升沿启动一轮测试（自动清零计数）
      Reset   : Bool;   // 清除结果与计数
      Tol     : Real := 0.001;   // 实数比较容差
   END_VAR

   VAR_OUTPUT
      Busy           : Bool;   // 测试进行中
      Done           : Bool;   // 本轮测试结束
      AllPassed      : Bool;   // Done 且 FailCount = 0
      PassCount      : Int;    // 通过用例数
      FailCount      : Int;    // 失败用例数
      FirstFailIndex : Int := -1;   // 第一条失败用例下标，-1 表示无
   END_VAR

   VAR
      Cases : Array[0..7] of Struct   // 用例表：在 DB 里直接编辑
         Enabled  : Bool;   // 是否参与本轮测试
         Input    : Real;   // 送入被测逻辑的输入
         Expected : Real;   // 预期输出
         Actual   : Real;   // 实际输出（由 RunCase 写回）
         Passed   : Bool;   // 本条结果
      END_STRUCT;
      CaseIndex  : Int;    // 当前执行到的用例
      StartEdge  : Bool;   // Start 上升沿记忆
      Running    : Bool;   // 内部运行标志
   END_VAR

   VAR_TEMP
      tmpDiff : Real;
   END_VAR

BEGIN
   // --- 复位 ---------------------------------------------------------------
   IF #Reset THEN
      #Running := FALSE;
      #Busy := FALSE;
      #Done := FALSE;
      #AllPassed := FALSE;
      #PassCount := 0;
      #FailCount := 0;
      #FirstFailIndex := -1;
      #CaseIndex := 0;
   END_IF;

   // --- Start 上升沿：清零并开始一轮 ------------------------------------------
   IF #Start AND NOT #StartEdge AND NOT #Running THEN
      #Running := TRUE;
      #Busy := TRUE;
      #Done := FALSE;
      #AllPassed := FALSE;
      #PassCount := 0;
      #FailCount := 0;
      #FirstFailIndex := -1;
      #CaseIndex := 0;
   END_IF;
   #StartEdge := #Start;

   // --- 每个周期跑一条用例，便于在监控表里逐条观察 ---------------------------
   IF #Running THEN
      IF #Cases[#CaseIndex].Enabled THEN
         // ===== RunCase：把被测逻辑放在这里（示例：0..100 -> 0..1000 线性缩放）=====
         #Cases[#CaseIndex].Actual := #Cases[#CaseIndex].Input * 10.0;
         // ==========================================================================

         #tmpDiff := ABS(#Cases[#CaseIndex].Actual - #Cases[#CaseIndex].Expected);
         #Cases[#CaseIndex].Passed := #tmpDiff <= #Tol;
         IF #Cases[#CaseIndex].Passed THEN
            #PassCount := #PassCount + 1;
         ELSE
            #FailCount := #FailCount + 1;
            IF #FirstFailIndex < 0 THEN
               #FirstFailIndex := #CaseIndex;
            END_IF;
         END_IF;
      END_IF;

      IF #CaseIndex >= 7 THEN
         #Running := FALSE;
         #Busy := FALSE;
         #Done := TRUE;
         #AllPassed := #FailCount = 0;
      ELSE
         #CaseIndex := #CaseIndex + 1;
      END_IF;
   END_IF;
END_FUNCTION_BLOCK

// ============================================================================
//  FB_StepSequenceDemo —— 步序状态机示例功能块
//  ---------------------------------------------------------------------------
//  功能：用 CASE 实现 4 步顺序流程（空闲→步10→步20→步30→回空闲）。
//        Next 上升沿推进步序，ConditionOk 作为进入/退出条件，并输出进度百分比。
//  适用：S7-1200 / S7-1500（优化访问）。顺序控制 / 工艺步进骨架。
//  作者：TIA MCP 示例库     版本：0.2
// ============================================================================
FUNCTION_BLOCK "FB_StepSequenceDemo"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.2
   VAR_INPUT
      Enable      : Bool;   // 使能：为 FALSE 时强制回到空闲步
      Next        : Bool;   // 步进请求：上升沿推进到下一步
      Reset       : Bool;   // 复位：高电平强制回到空闲步
      ConditionOk : Bool;   // 步序条件：满足时才允许进入/保持流程
   END_VAR

   VAR_OUTPUT
      StepNo   : Int;    // 当前步号（0=空闲, 10/20/30=各工作步）
      Ready    : Bool;   // 就绪：处于空闲步，等待启动
      Busy     : Bool;   // 运行中：处于中间工作步
      Done     : Bool;   // 完成：到达最后一步
      Progress : Real;   // 进度百分比 0/33/66/100，供 HMI 显示
   END_VAR

   VAR
      State    : Int;   // 状态机当前状态
      LastNext : Bool;  // 上一周期 Next 状态，用于上升沿检测
   END_VAR

BEGIN
   // --- 状态机主体 --------------------------------------------------------
   IF Reset OR NOT Enable THEN
      State := 0;                                  // 复位或未使能：回空闲步
   ELSE
      CASE State OF
         0:                                        // 空闲：条件满足则启动
            IF ConditionOk THEN State := 10; END_IF;
         10:                                       // 步10：Next 上升沿进入步20
            IF Next AND NOT LastNext THEN State := 20; END_IF;
         20:                                       // 步20：Next 上升沿进入步30
            IF Next AND NOT LastNext THEN State := 30; END_IF;
         30:                                       // 步30（完成）：条件消失则回空闲
            IF NOT ConditionOk THEN State := 0; END_IF;
      ELSE
         State := 0;                               // 非法状态保护：回空闲
      END_CASE;
   END_IF;
   LastNext := Next;                               // 记录 Next，供下次沿检测

   // --- 状态输出映射 ------------------------------------------------------
   StepNo := State;
   Ready  := (State = 0);
   Busy   := (State > 0) AND (State < 30);
   Done   := (State = 30);

   // --- 进度百分比（供 HMI 显示） -----------------------------------------
   CASE State OF
      0:   Progress := 0.0;
      10:  Progress := 33.0;
      20:  Progress := 66.0;
      30:  Progress := 100.0;
   ELSE
      Progress := 0.0;
   END_CASE;
END_FUNCTION_BLOCK

// ============================================================================
//  FB_TimerCounterDemo —— 边沿计数器示例功能块
//  ---------------------------------------------------------------------------
//  功能：对计数脉冲 CountPulse 的上升沿进行计数，累计值达到预设值后置位完成标志，
//        并输出运行标志、剩余计数与完成百分比，方便 HMI 直接显示进度。
//  适用：S7-1200 / S7-1500（优化访问）。纯布尔/整型/实型逻辑，不依赖定时器。
//  作者：TIA MCP 示例库     版本：0.3
// ============================================================================
FUNCTION_BLOCK "FB_TimerCounterDemo"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.3
   VAR_INPUT
      Enable      : Bool;   // 使能：为 TRUE 时才接受计数脉冲
      CountPulse  : Bool;   // 计数脉冲：每检测到一个上升沿，累计值 +1
      Reset       : Bool;   // 复位：高电平有效，将累计值清零（优先级最高）
      PresetCount : DInt;   // 预设计数值：累计值达到该值时置位 CounterDone
   END_VAR

   VAR_OUTPUT
      Running        : Bool;   // 运行中：已使能且尚未完成
      CounterDone    : Bool;   // 计数完成：累计值 >= 预设值
      CountValue     : DInt;   // 当前累计计数值（每周期输出）
      RemainingCount : DInt;   // 剩余计数 = 预设值 - 累计值（不小于 0）
      DonePercent    : Real;   // 完成百分比 0.0~100.0，供 HMI 进度条显示
   END_VAR

   VAR
      LastCountPulse : Bool;   // 上一扫描周期的脉冲状态，用于上升沿检测
      Accum          : DInt;   // 内部累计计数（静态保持，避免输出未初始化告警）
   END_VAR

BEGIN
   // --- 计数与复位逻辑 ----------------------------------------------------
   IF Reset THEN
      Accum := 0;                                        // 复位优先：清零累计值
   ELSIF Enable AND CountPulse AND NOT LastCountPulse THEN
      Accum := Accum + 1;                                // 仅在使能且脉冲上升沿时累加
   END_IF;
   LastCountPulse := CountPulse;                         // 记录本周期脉冲，供下次沿检测
   CountValue     := Accum;                              // 累计值每周期输出，保证已赋值

   // --- 完成与运行状态 ----------------------------------------------------
   CounterDone := (PresetCount > 0) AND (Accum >= PresetCount);
   Running     := Enable AND NOT CounterDone;

   // --- 剩余计数与完成百分比（供 HMI 显示） --------------------------------
   IF PresetCount > 0 THEN
      IF Accum < PresetCount THEN
         RemainingCount := PresetCount - Accum;
      ELSE
         RemainingCount := 0;                            // 已超过预设值则剩余记 0
      END_IF;
      DonePercent := LIMIT(MN := 0.0,
                           IN := DINT_TO_REAL(Accum) / DINT_TO_REAL(PresetCount) * 100.0,
                           MX := 100.0);
   ELSE
      RemainingCount := 0;                               // 未设定预设值时不计算剩余
      DonePercent    := 0.0;
   END_IF;
END_FUNCTION_BLOCK

// ============================================================================
//  FC_BasicScaleLimit —— 线性缩放与限幅功能（FC）
//  ---------------------------------------------------------------------------
//  功能：把原始量程 [RawMin, RawMax] 的输入线性映射到工程量程 [EngMin, EngMax]，
//        并限幅在工程上下限内；量程非法（RawMax = RawMin）时输出下限并报无效。
//        额外输出 Clamped 指示结果是否被限幅，便于诊断超量程。
//  适用：S7-1200 / S7-1500（优化访问）。模拟量工程值换算的标准骨架。
//  作者：TIA MCP 示例库     版本：0.2
// ============================================================================
FUNCTION "FC_BasicScaleLimit" : Void
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.2
   VAR_INPUT
      RawValue : Real;   // 原始输入值（如 AI 通道标定后的电流/电压值）
      RawMin   : Real;   // 原始量程下限
      RawMax   : Real;   // 原始量程上限
      EngMin   : Real;   // 工程量程下限
      EngMax   : Real;   // 工程量程上限
   END_VAR

   VAR_OUTPUT
      EngValue : Real;   // 换算并限幅后的工程值
      Valid    : Bool;   // 换算有效（量程合法）
      Clamped  : Bool;   // 结果被上/下限限幅（输入超量程）
   END_VAR

   VAR_TEMP
      Scaled : Real;     // 限幅前的线性换算中间值
   END_VAR

BEGIN
   IF RawMax <> RawMin THEN
      // 线性插值：EngMin + (输入占原始量程比例) * 工程量程跨度
      Scaled   := EngMin + ((RawValue - RawMin) * (EngMax - EngMin) / (RawMax - RawMin));
      EngValue := LIMIT(MN := EngMin, IN := Scaled, MX := EngMax);   // 限幅在工程上下限
      Valid    := TRUE;
      Clamped  := (Scaled <> EngValue);          // 限幅前后不一致说明发生了限幅
   ELSE
      EngValue := EngMin;                         // 量程非法：输出下限并报无效
      Valid    := FALSE;
      Clamped  := FALSE;
   END_IF;
END_FUNCTION

FUNCTION "FC_InstructionGallery" : Void
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT
      Enable : Bool;
      Mode : Int;
      InInt : Int;
      InDInt : DInt;
      InReal : Real;
      MinValue : Real;
      MaxValue : Real;
   END_VAR

   VAR_OUTPUT
      OutBool : Bool;
      OutInt : Int;
      OutDInt : DInt;
      OutReal : Real;
      InRange : Bool;
   END_VAR

   VAR_TEMP
      Index : Int;
      SumValue : DInt;
      RealFromDInt : Real;
   END_VAR

BEGIN
   OutBool := Enable AND (Mode >= 0);
   OutInt := InInt;
   OutDInt := InDInt;
   RealFromDInt := DINT_TO_REAL(InDInt);

   IF NOT Enable THEN
      OutReal := 0.0;
   ELSIF Mode = 1 THEN
      OutReal := LIMIT(MN := MinValue, IN := InReal, MX := MaxValue);
   ELSIF Mode = 2 THEN
      OutReal := ABS(InReal);
   ELSE
      OutReal := RealFromDInt;
   END_IF;

   CASE Mode OF
      0:
         OutInt := 0;
      1:
         OutInt := InInt + 1;
      2:
         OutInt := InInt - 1;
   ELSE
      OutInt := InInt;
   END_CASE;

   SumValue := 0;
   FOR Index := 0 TO 7 DO
      SumValue := SumValue + INT_TO_DINT(Index);
   END_FOR;

   OutDInt := SumValue;
   InRange := (OutReal >= MinValue) AND (OutReal <= MaxValue);
END_FUNCTION

// ============================================================================
//  FC_MathCompareDemo —— 偏差运算 / 比较 / 限幅 / 质量位示例（FC）
//  ---------------------------------------------------------------------------
//  功能：计算设定值与实际值的偏差及绝对偏差，按死区判断是否在公差内，
//        输出限幅后的偏差值，并给出高于/低于设定值及偏差百分比，便于调节与显示。
//  适用：S7-1200 / S7-1500（优化访问）。闭环调节前处理 / 偏差监视骨架。
//  作者：TIA MCP 示例库     版本：0.2
// ============================================================================
FUNCTION "FC_MathCompareDemo" : Void
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.2
   VAR_INPUT
      Setpoint : Real;   // 设定值
      Actual   : Real;   // 实际值
      Deadband : Real;   // 死区（绝对偏差 <= 死区视为在公差内）
      OutMin   : Real;   // 偏差输出下限
      OutMax   : Real;   // 偏差输出上限
   END_VAR

   VAR_OUTPUT
      ErrorValue   : Real;   // 偏差 = 设定值 - 实际值
      AbsError     : Real;   // 绝对偏差
      OutputValue  : Real;   // 限幅后的偏差值（可作为调节量）
      InTolerance  : Bool;   // 在公差内（绝对偏差 <= 死区）
      AboveSetpoint: Bool;   // 实际值高于设定值
      DeviationPct : Real;   // 相对设定值的偏差百分比（设定值为 0 时记 0）
   END_VAR

BEGIN
   // --- 偏差与绝对偏差 ----------------------------------------------------
   ErrorValue := Setpoint - Actual;
   AbsError   := ABS(ErrorValue);

   // --- 限幅输出与公差判断 ------------------------------------------------
   OutputValue := LIMIT(MN := OutMin, IN := ErrorValue, MX := OutMax);
   InTolerance := AbsError <= Deadband;

   // --- 方向与偏差百分比（供 HMI 显示） -----------------------------------
   AboveSetpoint := Actual > Setpoint;
   IF Setpoint <> 0.0 THEN
      DeviationPct := AbsError / ABS(Setpoint) * 100.0;
   ELSE
      DeviationPct := 0.0;                       // 设定值为 0 时不计算百分比
   END_IF;
END_FUNCTION

